/** enforce facades and table owners */
function facadeViolations({ imports, queries, owners }) {
  // Write your solution here
  const out = [];
  for (const { from, to } of imports) if (to.includes('/internal/')) out.push('IMPORT_INTERNAL ' + from + ' -> ' + to);
  return out;
}

